"""Generate pinned musl wide numeric wrappers around the shared string scan cursor."""
from pathlib import Path
import argparse,difflib,hashlib,json,shutil
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--musl-root',required=True,type=Path);p.add_argument('--numeric-root',required=True,type=Path);p.add_argument('--output-dir',required=True,type=Path);a=p.parse_args()
out=a.output_dir;out.mkdir(parents=True,exist_ok=False);(out/'originals').mkdir();(out/'patches').mkdir()
manifest={'version':'musl 1.2.6','releaseSha256':'d585fd3b613c66151fc3249e8ed44f77020cb5e6c1e635a616d3f9f82460512a','sources':{},'adapters':{}}
prefix_wcstol='#include "wide_numeric.h"\n#include "../strto/intscan.h"\n#include <inttypes.h>\n#include <limits.h>\nstatic unsigned long long wcstox(const wchar_t *s,wchar_t **p,int base,unsigned long long lim)\n{\n const wchar_t *t=s;while(iswspace(*t))++t;\n struct edg_string_scan f;sh_fromwide(&f,t);shlim(&f,0);\n unsigned long long value=__intscan(&f,base,1,lim);\n if(p){size_t count=shcnt(&f);*p=(wchar_t *)(count?t+count:s);}\n return value;\n}\n\n'
prefix_wcstod='#include "wide_numeric.h"\n#include "../strto/floatscan.h"\n#include <errno.h>\n#include <float.h>\nstatic long double wcstox(const wchar_t *s,wchar_t **p,int precision)\n{\n const wchar_t *t=s;while(iswspace(*t))++t;\n struct edg_string_scan f;sh_fromwide(&f,t);shlim(&f,0);\n long double value=__floatscan(&f,precision,1);\n if(p){size_t count=shcnt(&f);*p=(wchar_t *)(count?t+count:s);}\n return value;\n}\n\n'
for name in ['wcstol.c','wcstod.c']:
 original=(a.musl_root/'src/stdlib'/name).read_text()
 if name=='wcstol.c':adapted=prefix_wcstol+original[original.index('unsigned long long wcstoull'):]
 else:
  narrow=(a.numeric_root/'strtod.c').read_text();body=narrow[narrow.index('float strtof'):]
  for old,new in [('strtof','wcstof'),('strtod','wcstod'),('strtold','wcstold'),('strtox','wcstox'),('const char *s','const wchar_t *s'),('char **p','wchar_t **p')]:body=body.replace(old,new)
  adapted=prefix_wcstod+body
 (out/'originals'/name).write_text(original);(out/name).write_text(adapted)
 (out/'patches'/(name+'.patch')).write_text(''.join(difflib.unified_diff(original.splitlines(True),adapted.splitlines(True),fromfile='a/'+name,tofile='b/'+name)))
 manifest['sources'][name]={'upstream':'src/stdlib/'+name,'originalSha256':hashlib.sha256(original.encode()).hexdigest(),'adaptedSha256':hashlib.sha256(adapted.encode()).hexdigest()}
content='#ifndef EDG_WIDE_NUMERIC_H\n#define EDG_WIDE_NUMERIC_H\n#include <wchar.h>\n#include <wctype.h>\n#include <locale.h>\n#include <inttypes.h>\n#include "../strto/scan_string.h"\n#ifdef __cplusplus\n#define restrict __restrict\nextern "C" {\n#endif\nint __edg_locale_validate(locale_t);\nfloat wcstof_l(const wchar_t *,wchar_t **,locale_t);\ndouble wcstod_l(const wchar_t *,wchar_t **,locale_t);\nlong double wcstold_l(const wchar_t *,wchar_t **,locale_t);\nlong wcstol_l(const wchar_t *,wchar_t **,int,locale_t);\nunsigned long wcstoul_l(const wchar_t *,wchar_t **,int,locale_t);\nlong long wcstoll_l(const wchar_t *,wchar_t **,int,locale_t);\nunsigned long long wcstoull_l(const wchar_t *,wchar_t **,int,locale_t);\n\n#ifdef __cplusplus\n}\n#endif\n#endif\n';(out/'wide_numeric.h').write_text(content);manifest["adapters"]['wide_numeric.h']=hashlib.sha256(content.encode()).hexdigest()
content='#include "wide_numeric.h"\nfloat wcstof_l(const wchar_t *s,wchar_t **end,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstof(s,end);\n}\ndouble wcstod_l(const wchar_t *s,wchar_t **end,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstod(s,end);\n}\nlong double wcstold_l(const wchar_t *s,wchar_t **end,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstold(s,end);\n}\nlong wcstol_l(const wchar_t *s,wchar_t **end,int base,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstol(s,end,base);\n}\nunsigned long wcstoul_l(const wchar_t *s,wchar_t **end,int base,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstoul(s,end,base);\n}\nlong long wcstoll_l(const wchar_t *s,wchar_t **end,int base,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstoll(s,end,base);\n}\nunsigned long long wcstoull_l(const wchar_t *s,wchar_t **end,int base,locale_t locale)\n{\n if(!__edg_locale_validate(locale)){if(end)*end=(wchar_t*)s;return 0;}\n return wcstoull(s,end,base);\n}\n';(out/'wide_locale_wrappers.c').write_text(content);manifest["adapters"]['wide_locale_wrappers.c']=hashlib.sha256(content.encode()).hexdigest()
(out/'source.json').write_text(json.dumps(manifest,indent=2)+'\n');shutil.copyfile(a.musl_root/'COPYRIGHT',out/'COPYRIGHT')
print('3 translation units; shared strto/scan_string.h must provide sh_fromwide')
